// Close it immediately using all available budget, then skip Phase 1.
if insideConstrainedOut && steps < maxSteps {
  var closeBudget0 := maxSteps - steps;
  var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget0
  );
  generated := cg0;
  insideConstrainedOut := ci0;
  currentConstrainedOut := cc0;
  steps := maxSteps;
}

// Phase 1 — Fully unconstrained reasoning.
// Reserve 51 steps for Phase 2 (1 for "<<" + 50 for expression generation).
// The model generates its natural step-by-step solution.  Any inline "<<...>>"
// it emits becomes free text in `generated`; we do NOT enter constrained mode.
var reservedSteps: nat := 51;
